import{c as o,Q as t,j as l,m as s}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"Goal + Loop + Workflows 三大利器","description":"","frontmatter":{"url":"https://x.com/pandatalk8/status/2065714368071745710","title":"Goal + Loop + Workflows 三大利器","author":"PandaTalk8","archived":"2026-06-14T00:00:00.000Z","handle":"@PandaTalk8","published":"2026-06-13T00:00:00.000Z","stats":"201 likes · 39 retweets · 496 bookmarks · 45284 views","tags":["claude-code","goal","loop","workflows","multi-agent","agentic"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-06-13-@PandaTalk8-745710.md","filePath":"research/tweets/2026-06-13-@PandaTalk8-745710.md","lastUpdated":1785909234000}'),e={name:"research/tweets/2026-06-13-@PandaTalk8-745710.md"};function n(p,a,r,d,i,u){return t(),l("div",null,[...a[0]||(a[0]=[s(`<h1 id="goal-loop-workflows-三大利器-—-pandatalk8" tabindex="-1">Goal + Loop + Workflows 三大利器 — @PandaTalk8 <a class="header-anchor" href="#goal-loop-workflows-三大利器-—-pandatalk8" aria-label="Permalink to &quot;Goal + Loop + Workflows 三大利器 — @PandaTalk8&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/pandatalk8/status/2065714368071745710" target="_blank" rel="noreferrer">https://x.com/pandatalk8/status/2065714368071745710</a><strong>作者</strong>：PandaTalk8（@PandaTalk8） <strong>發布日期</strong>：2026-06-13 <strong>收錄日期</strong>：2026-06-14 <strong>類型</strong>：Twitter Article <strong>統計</strong>：201 likes · 39 retweets · 496 bookmarks · 45284 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><h1 id="有什么区别" tabindex="-1">有什么区别 <a class="header-anchor" href="#有什么区别" aria-label="Permalink to &quot;有什么区别&quot;">​</a></h1><p>你让 Claude 跑一个任务，它干完一轮，停下来，等你说下一句。这是大多数人用 Claude Code 的方式——一问一答，像在跟一个反应很快但没什么主见的助理对话。</p><p>但有三个命令能改变这种交互：/goal、/loop、/workflows。很多人把它们混为一谈，觉得都是&quot;让 Claude 自己多干会儿&quot;。</p><p>这是个误解。它们解决的根本不是同一个问题。</p><p>/goal 回答的是&quot;什么时候算干完&quot;，/loop 回答的是&quot;隔多久干一次&quot;，/workflows 回答的是&quot;一次铺开多少个 Claude 一起干&quot;。一个管终点，一个管节奏，一个管规模。搞清楚这三个维度，你才知道手上的活该交给谁。</p><h1 id="一、先看一张表" tabindex="-1">一、先看一张表 <a class="header-anchor" href="#一、先看一张表" aria-label="Permalink to &quot;一、先看一张表&quot;">​</a></h1><table tabindex="0"><thead><tr><th>命令</th><th>本质</th><th>由什么驱动</th><th>智能体数量</th></tr></thead><tbody><tr><td><strong><code>/goal</code></strong></td><td>自主跑到目标达成为止</td><td><strong>条件满足</strong>才停</td><td>1 个（当前会话，多轮）</td></tr><tr><td><strong><code>/loop</code></strong></td><td>按节奏重复同一件事</td><td><strong>时间间隔</strong>到点就跑</td><td>1 个（当前会话，多轮）</td></tr><tr><td><strong><code>/workflows</code></strong></td><td>多智能体并行编排的控制台</td><td>看一个已启动 Workflow 的<strong>实时进度</strong></td><td>多个（几个到几十个并行）</td></tr></tbody></table><p>前两个是&quot;纵向&quot;的——同一个 Claude，多跑几轮，区别只在什么时候停。第三个是&quot;横向&quot;的——一次拉起一群 Claude，各干各的，再汇总。</p><h2 id="二、-goal-盯着一个终点-自己跑到达成" tabindex="-1">二、/GOAL：盯着一个终点，自己跑到达成 <a class="header-anchor" href="#二、-goal-盯着一个终点-自己跑到达成" aria-label="Permalink to &quot;二、/GOAL：盯着一个终点，自己跑到达成&quot;">​</a></h2><p>/goal 的核心是把&quot;完成&quot;这件事从你手里交出去，交给一个可验证的条件。</p><p>平常你怎么知道任务做完了？你看一眼输出，觉得差不多了，就停。/goal 把这个判断自动化了：你先用一句话说清楚&quot;什么叫做完&quot;，然后 Claude 一轮接一轮自己干，每轮结束后，一个轻量评估模型去检查——条件满足了吗？满足，自动收手；不满足，接着下一轮。</p><p>你不用每轮都催&quot;继续&quot;&quot;再改改&quot;。</p><p>怎么用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/goal test/auth 下所有测试通过且 lint 全绿</span></span></code></pre></div><p>Claude 会反复改代码、跑测试，每轮后让评估模型核对&quot;测试全过 + lint 干净&quot;这个条件，达标才停。</p><p>什么场景适合它？有明确验收标准的离散任务。</p><ul><li>把一个模块迁移到新 API，直到所有调用点编译通过、测试全绿</li><li>照着一份设计文档实现，直到所有验收标准满足</li><li>把一个超大文件拆成小模块，直到每个都在体积预算内</li><li>处理一串标记好的 issue，直到队列清空</li></ul><p>这些任务的共同点是：终点是客观的，能被机器验证。你能写出一句&quot;满足 X 就算完&quot;，/goal 就能替你盯着这个 X。</p><h2 id="三、-loop-定时重复-做轮询和值守" tabindex="-1">三、/LOOP：定时重复，做轮询和值守 <a class="header-anchor" href="#三、-loop-定时重复-做轮询和值守" aria-label="Permalink to &quot;三、/LOOP：定时重复，做轮询和值守&quot;">​</a></h2><p>/loop 不关心&quot;做没做完&quot;，它只关心&quot;到点了没有&quot;。</p><p>它按一个固定的时间间隔，反复运行同一个 prompt 或命令。时间到，就跑一次；你不喊停，它就一直转下去。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/loop 5m 检查部署状态，有变化就告诉我</span></span></code></pre></div><p>每隔五分钟，Claude 去看一眼部署，有动静就汇报。这是典型的&quot;值守&quot;模式——盯着一个会变的外部状态，等它发生变化。</p><p>适合的场景：</p><ul><li>每隔几分钟看一次 CI 跑完没有</li><li>轮询一个远程任务队列</li><li>定时扫一遍 PR 列表，有新的就处理</li></ul><p>/loop 和 /goal 最容易被搞混，但它俩的停止逻辑正好相反。</p><p>/goal 是&quot;达标即停&quot;——目标达成，任务结束。/loop 是&quot;到点就跑&quot;——只要你不手动停，它就永远转下去，因为时间永远在走。一个有终点，一个没终点。</p><p>还有个细节：/loop 如果不指定间隔，可以让模型自己决定下次什么时候醒。这适合那种&quot;我也不知道该几分钟看一次&quot;的情况——让 Claude 根据它在等的东西（CI 大概八分钟、远程队列变化更慢）自己挑节奏。</p><h2 id="四、-workflows-一群-claude-并行干活的监控面板" tabindex="-1">四、/WORKFLOWS：一群 CLAUDE 并行干活的监控面板 <a class="header-anchor" href="#四、-workflows-一群-claude-并行干活的监控面板" aria-label="Permalink to &quot;四、/WORKFLOWS：一群 CLAUDE 并行干活的监控面板&quot;">​</a></h2><p>前面两个命令，从头到尾都只有一个 Claude 在跑，只是多跑几轮。/workflows 是另一个维度的东西。</p><p>它配套的是 Workflow（多智能体编排）：一段脚本把一个大任务拆开，同时拉起几个到几十个子智能体并行干活——分头审查不同文件、分头迁移不同模块、分头从不同角度调研——然后把结果汇总回来。</p><p>/workflows 本身不发起任务，它是你用来实时观看这群并行智能体进度的命令。就像一个调度大屏：哪个智能体在跑哪一步、哪个跑完了、整体到哪了，一目了然。</p><p>什么时候需要它？当一个任务大到单个 Claude 的上下文装不下，或者需要分头覆盖、交叉验证的时候。</p><ul><li>一次代码评审，拆成多个维度（正确性、安全、性能）并行跑，再把发现汇总</li><li>几十个文件的批量迁移，一个智能体管一个文件，互不干扰</li><li>多路并行调研同一个问题，再做对抗式验证、综合成报告</li></ul><p>这种&quot;分头干 + 汇总&quot;的结构，是单线程多轮做不到的——你没法让一个 Claude 同时待在三个文件里。</p><p>有一点要提醒：多智能体编排很烧 token。一次能拉起几十个智能体，消耗是单线程的好几倍，所以它通常需要你显式要求（比如直接说&quot;用 workflow 来做这个&quot;）才会启动，不会自动触发。而 /workflows 只是看进度的窗口，不花钱也不发起任务。</p><h2 id="五、到底该选哪个" tabindex="-1">五、到底该选哪个 <a class="header-anchor" href="#五、到底该选哪个" aria-label="Permalink to &quot;五、到底该选哪个&quot;">​</a></h2><p>把决策简化成三句话：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>有明确&quot;做完&quot;的判据    →  /goal       （达标即停）</span></span>
<span class="line"><span>要按时间反复盯一件事  →  /loop       （定时轮询）</span></span>
<span class="line"><span>活太大要分头并行干    →  Workflow，用 /workflows 看进度</span></span></code></pre></div><p>再说透一层：</p><p>/goal 和 /loop 都是单会话、多轮、一个 Claude，区别只在停止条件——一个看目标，一个看时钟。/workflows 管的是另一码事：它不是让一个 Claude 多跑几轮，而是让一群 Claude 横向铺开同时干。</p><p>纵向的深度，和横向的规模，是两个正交的维度。想清楚你缺的是哪一个，就不会选错。</p><h2 id="六、用-goal-会自动调用-loop-或-workflows-吗" tabindex="-1">六、用 /GOAL 会自动调用 /LOOP 或 /WORKFLOWS 吗？ <a class="header-anchor" href="#六、用-goal-会自动调用-loop-或-workflows-吗" aria-label="Permalink to &quot;六、用 /GOAL 会自动调用 /LOOP 或 /WORKFLOWS 吗？&quot;">​</a></h2><p>不会。这是个常见的误会——很多人以为 /goal 是个&quot;总指挥&quot;，底层会去调度另外两个。其实三者机制完全独立。</p><p>/goal 的多轮循环，不靠 /loop。它能一轮接一轮跑，靠的是自己内建的机制：每轮干完，评估模型判断条件达没达成，没达成就续一轮。这套循环和 /loop 的定时器是两码事，不共用。</p><p>/goal 也不会自动开 Workflow。多智能体编排很烧 token，按设计必须你显式要求才会启动，不会被 /goal 悄悄拉起来。</p><p>但有一层区别要分清——&quot;/goal 调用它们&quot;和&quot;/goal 跑的过程中 Claude 自己决定用某个工具&quot;，是两回事。</p><p>/goal 只负责一件事：判断&quot;做完了没有&quot;，没做完就让 Claude 再跑一轮。至于每一轮里 Claude 具体怎么干、用哪些工具，是 Claude 自己的决策。所以如果你在一个 /goal 任务里明确说了&quot;可以用 workflow 并行处理&quot;，Claude 某一轮里确实可能去发起一个 Workflow——但这是它在执行层的选择，不是 /goal 这个命令本身的行为。</p><p>/goal 是个裁判，只管吹哨判断比赛结不结束，它不规定运动员怎么踢。/loop 的定时器、/workflows 的并行编排，都是另外的机制，/goal 不会自动替你启动。</p><h2 id="七、高频错误用法" tabindex="-1">七、高频错误用法 <a class="header-anchor" href="#七、高频错误用法" aria-label="Permalink to &quot;七、高频错误用法&quot;">​</a></h2><p>知道三个命令各管什么还不够，真正容易踩坑的是&quot;选错了那一个&quot;。下面是最常见的几种误用，几乎每个刚上手的人都犯过。</p><p><strong>错误一：用 /loop 干 /goal 的活</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># ❌ 错误</span></span>
<span class="line"><span>/loop 2m 把测试都修复了</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ✅ 正确</span></span>
<span class="line"><span>/goal 所有测试通过</span></span></code></pre></div><p>修测试有明确终点——测试全过就完事了。用 /loop 等于让它每两分钟无脑跑一次，测试早就过了它还在转，因为定时器不认终点。这种活天生属于 /goal。</p><p>判断标准：你能说出一句&quot;满足 X 就算完&quot;，就用 /goal，不要用 /loop。</p><p><strong>错误二：给 /goal 一个没法验证的条件</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># ❌ 错误</span></span>
<span class="line"><span>/goal 把代码写得优雅一点</span></span>
<span class="line"><span>/goal 让这个功能体验更好</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ✅ 正确</span></span>
<span class="line"><span>/goal 这个函数圈复杂度降到 10 以下，且单测覆盖率超过 80%</span></span></code></pre></div><p>&quot;优雅&quot;&quot;更好&quot;这类词，评估模型没法客观判断达没达成——于是 /goal 要么提前停，要么永远不停。/goal 的条件必须是机器能验证的：测试、编译、数值阈值、文件状态。主观目标喂给它，等于没给。</p><p><strong>错误三：拿 /loop 当后台监工，盲目压缩间隔</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># ❌ 错误</span></span>
<span class="line"><span>/loop 30s 看看那个要跑十分钟的 CI 好了没</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ✅ 正确</span></span>
<span class="line"><span>/loop 3m 看看 CI 好了没</span></span></code></pre></div><p>一个要十分钟的 CI，你每 30 秒查一次——查二十次才等到结果，前十九次纯属浪费 token，还把缓存反复打掉。间隔要匹配你在等的东西变化的真实速度，不是越短越&quot;及时&quot;。</p><p><strong>错误四：屁大点事就上 Workflow</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># ❌ 错误</span></span>
<span class="line"><span>&quot;用 workflow 帮我改个错别字&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ✅ 正确</span></span>
<span class="line"><span>直接让 Claude 改，一句话的事</span></span></code></pre></div><p>多智能体并行的代价是 token 翻好几倍，只有&quot;单个上下文装不下&quot;或&quot;需要分头覆盖、交叉验证&quot;的大活才值得。改错别字、加个函数、查一个文件这种，拉起一群智能体是杀鸡用牛刀，慢、贵，还没好处。</p><p><strong>错误五：以为 /workflows 能发起任务</strong></p><p>/workflows 只是看进度的窗口，它本身不启动任何东西。想跑并行编排得先发起一个 Workflow（显式要求），/workflows 是用来盯着它跑的。把它当成&quot;启动并行&quot;的开关，会发现什么都没发生。</p><p>把这五条反过来，其实就是三个命令的正确用法：终点明确且可验证 → /goal；盯外部状态变化、间隔匹配真实节奏 → /loop；活大到要分头干 → Workflow，再用 /workflows 看进度。</p><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>这三个命令背后，其实是同一个趋势：人和 AI 的交互，正在从&quot;一问一答&quot;变成&quot;交代一个目标，然后走开&quot;。</p><p>/goal 让你不用盯着每一轮，/loop 让你不用守着时钟，/workflows 让你不用一个文件一个文件地排队。它们省下的，都是你本来要花在&quot;催促&quot;和&quot;调度&quot;上的注意力。</p><p>下次再开一个长任务前，先问自己一句：我到底是缺一个终点判断，还是缺一个定时器，还是缺一群帮手？答案，就是该用哪个命令。</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：/goal（達標即停）、/loop（定時輪詢）、/workflows（多 agent 並行監控）是三個正交維度：終點、節奏、規模，各自解決不同的問題，不可混用。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li><strong>三維度區分</strong>：/goal 管「何時完成」（條件驅動）、/loop 管「多久跑一次」（時間驅動）、/workflows 管「多少 Claude 並行」（規模維度）</li><li><strong>縱向 vs 橫向</strong>：前兩者是縱向（同一 Claude 多輪）；/workflows 是橫向（多 Claude 並行）——兩個正交維度</li><li><strong>/goal 的條件必須是機器可驗證的</strong>：「優雅」「體驗更好」是無效條件，測試通過/lint 綠/數值閾值才是合格條件</li><li><strong>/loop 間隔要匹配真實變化節奏</strong>：CI 要 10 分鐘，30 秒輪詢 = 浪費 token + 破快取</li><li><strong>三者機制完全獨立</strong>：/goal 不會自動調用 /loop 或 Workflow，Workflow 必須顯式觸發</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li><code>/goal</code>：輕量評估模型在每輪後判斷條件是否達成</li><li><code>/loop</code>：未指定間隔時可讓模型自決下次醒來時機</li><li><code>/workflows</code>：只是監控視窗，不發起任何任務，不消耗 token</li><li>Workflow（多智能體編排）：token 消耗是單線程數倍，需顯式要求才啟動</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>文章清晰但基於 Claude Code 特定實作細節；這些命令的行為若後續版本有變，文章即過時</li><li>「/goal 用評估模型判斷」這個機制細節值得深挖——評估模型如何處理模糊或部分達成的條件？</li><li>多智能體 Workflow 的啟動方式（「顯式要求」）描述較模糊，新用戶可能仍不清楚具體如何觸發</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>9/10</td><td>直接解釋 Claude Code 三個核心指令，含正確/錯誤用法對比，立即可用</td></tr><tr><td>B. 創新性 (20%)</td><td>7/10</td><td>「縱向/橫向」正交框架清晰，將三個命令放在統一維度下比較</td></tr><tr><td>C. 證據品質 (20%)</td><td>7/10</td><td>具體代碼範例和反模式，邏輯自洽，無需外部驗證</td></tr><tr><td>D. 技術深度 (15%)</td><td>7/10</td><td>解釋了內部機制（評估模型、定時器獨立性、token 成本）</td></tr><tr><td>E. 泛化性 (15%)</td><td>6/10</td><td>限 Claude Code 用戶，但覆蓋所有使用 /goal//loop//workflows 的場景</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.5/10</strong></td><td>9×0.3+7×0.2+7×0.2+7×0.15+6×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：總分 7.5 &gt; 6，核心是 Claude Code agentic 指令的使用原則與決策框架。</p>`,88)])])}const g=o(e,[["render",n]]);export{c as __pageData,g as default};
